    """Failure while preparing or reading a Responses API call.

    The message never includes the prompt or API key. ``status`` is the HTTP
    status when the failure came from the API.
    """

    def __init__(
        self,
        message: str,
        *,
        status: int | None = None,
        code: str | None = None,
    ) -> None:
        super().__init__(message)
        self.status = status
        self.code = code


class _RejectRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):  # noqa: ARG002
        raise OpenAIError(
            f"refusing to follow HTTP redirect ({code})",
            status=code,
        )


class OpenAIClient:
    """Stateless client for one private text prompt per request."""

    def __init__(
        self,
        *,
        api_key: str | None = None,
        base_url: str | None = None,
        model: str | None = None,
        timeout: float = 120,
    ) -> None:
        resolved_key = api_key if api_key is not None else os.environ.get("OPENAI_API_KEY")
        if not resolved_key or not resolved_key.strip():
            raise OpenAIError("OPENAI_API_KEY is not set")
        if any(char.isspace() for char in resolved_key):
            raise OpenAIError("API key must not contain whitespace")
        resolved_url = base_url if base_url is not None else os.environ.get(
            "OPENAI_BASE_URL",
            DEFAULT_BASE_URL,
        )
        resolved_model = model if model is not None else os.environ.get("OPENAI_MODEL")
        self._api_key = resolved_key.strip()
        self.base_url = _validate_base_url(resolved_url)
        self.model = _optional_model(resolved_model)
        self.timeout = _timeout(timeout)

    def __repr__(self) -> str:
        return f"OpenAIClient(base_url={self.base_url!r}, model={self.model!r})"

    def create(
        self,
        prompt: str,
        *,
        model: str | None = None,
        instructions: str | None = None,
        max_output_tokens: int | None = None,
        timeout: float | None = None,
    ) -> dict[str, Any]:
        """POST a text prompt and return the parsed JSON response object."""
        payload: dict[str, Any] = {
            "model": _require_model(model if model is not None else self.model),
            "input": _prompt(prompt),
            "store": False,
        }
        if instructions is not None:
            if not isinstance(instructions, str) or not instructions.strip():
                raise OpenAIError("instructions must be a non-empty string")
            payload["instructions"] = instructions
        if max_output_tokens is not None:
            if isinstance(max_output_tokens, bool) or not isinstance(max_output_tokens, int):
                raise OpenAIError("max_output_tokens must be a positive integer")
            if max_output_tokens < 1:
                raise OpenAIError("max_output_tokens must be a positive integer")
            payload["max_output_tokens"] = max_output_tokens
        return self._post(payload, self.timeout if timeout is None else _timeout(timeout))

    def send(
        self,
        prompt: str,
        *,
        model: str | None = None,
        instructions: str | None = None,
        max_output_tokens: int | None = None,
        timeout: float | None = None,
    ) -> str:
        """Send a text prompt and return the assistant'"'s output text.\"\"\"
        return extract_output_text(
            self.create(
                prompt,
                model=model,
                instructions=instructions,
                max_output_tokens=max_output_tokens,
                timeout=timeout,
            )
        )

    def _post(self, payload: dict[str, Any], timeout: float) -> dict[str, Any]:
        body = json.dumps(payload, ensure_ascii=False).encode(\"utf-8\")
        request = urllib.request.Request(
            f\"{self.base_url}/responses\",
            data=body,
            method=\"POST\",
            headers={
                \"Authorization\": f\"Bearer {self._api_key}\",
                \"Content-Type\": \"application/json\",
                \"Accept\": \"application/json\",
                \"User-Agent\": _USER_AGENT,
            },
        )
        opener = urllib.request.build_opener(
            urllib.request.ProxyHandler({}),
            _RejectRedirect,
            urllib.request.HTTPSHandler(context=ssl.create_default_context()),
        )
        try:
            with opener.open(request, timeout=timeout) as response:
                raw = response.read()
                status = getattr(response, \"status\", None)
        except OpenAIError:
            raise
        except urllib.error.HTTPError as exc:
            raw = exc.read()
            raise _api_error(exc.code, raw) from None
        except urllib.error.URLError as exc:
            raise OpenAIError(\"network error calling the Responses API\") from None
        except TimeoutError:
            raise OpenAIError(\"Responses API request timed out\") from None
        except OSError:
            raise OpenAIError(\"network error calling the Responses API\") from None

        parsed = _parse_json(raw)
        if status is not None and status >= 400:
            raise _api_error(status, raw)
        if isinstance(parsed.get(\"error\"), dict) and parsed.get(\"status\") == \"failed\":
            error = parsed[\"error\"]
            raise OpenAIError(
                _error_message(error.get(\"message\")),
                code=_optional_code(error.get(\"code\")),
            )
        return parsed


