        instructions=instructions,
        max_output_tokens=max_output_tokens,
        timeout=timeout,
    )


def extract_output_text(response: dict[str, Any]) -> str:
    \"\"\"Collect "'``output_text`` parts from a Responses API object."""
    if not isinstance(response, dict):
        raise OpenAIError("response must be a JSON object")
    direct = response.get("output_text")
    if isinstance(direct, str) and direct:
        return direct

    parts: list[str] = []
    refusals: list[str] = []
    output = response.get("output")
    if isinstance(output, list):
        for item in output:
            if not isinstance(item, dict):
                continue
            if item.get("type") == "refusal" and isinstance(item.get("refusal"), str):
                refusals.append(item["refusal"])
            content = item.get("content")
            if not isinstance(content, list):
                continue
            for block in content:
                if not isinstance(block, dict):
                    continue
                if block.get("type") == "output_text" and isinstance(block.get("text"), str):
                    parts.append(block["text"])
                elif block.get("type") == "refusal" and isinstance(block.get("refusal"), str):
                    refusals.append(block["refusal"])

    text = "".join(parts)
    if text:
        return text
    if refusals:
        raise OpenAIError("model refused the prompt")
    status = response.get("status")
    if isinstance(status, str) and status not in {"completed", ""}:
        raise OpenAIError(f"response status is {status}")
    raise OpenAIError("response did not include output text")


def _validate_base_url(url: str) -> str:
    if not isinstance(url, str) or not url.strip():
        raise OpenAIError("base URL must be an https URL")
    parsed = urllib.parse.urlparse(url.strip())
    host = (parsed.hostname or "").lower()
    if parsed.username or parsed.password or parsed.query or parsed.fragment:
        raise OpenAIError("base URL must not include credentials, query, or fragment")
    if parsed.scheme == "https" and host:
        return url.strip().rstrip("/")
    if parsed.scheme == "http" and host in _LOCAL_HOSTS:
        return url.strip().rstrip("/")
    raise OpenAIError("base URL must be https so prompts are not sent in cleartext")


def _optional_model(model: str | None) -> str | None:
    if model is None:
        return None
    return _require_model(model)


def _require_model(model: str | None) -> str:
    if not isinstance(model, str) or not model.strip():
        raise OpenAIError("model is required; pass model or set OPENAI_MODEL")
    if any(char.isspace() for char in model):
        raise OpenAIError("model must not contain whitespace")
    return model.strip()


def _prompt(prompt: str) -> str:
    if not isinstance(prompt, str):
        raise OpenAIError("prompt must be a string")
    if not prompt.strip():
        raise OpenAIError("prompt must not be empty")
    return prompt


def _timeout(timeout: float) -> float:
    if isinstance(timeout, bool) or not isinstance(timeout, (int, float)):
        raise OpenAIError("timeout must be a positive number of seconds")
    if timeout <= 0:
        raise OpenAIError("timeout must be a positive number of seconds")
    return float(timeout)


def _parse_json(raw: bytes) -> dict[str, Any]:
    try:
        parsed = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise OpenAIError("Responses API returned invalid JSON") from None
    if not isinstance(parsed, dict):
        raise OpenAIError("Responses API returned invalid JSON")
    return parsed


def _api_error(status: int, raw: bytes) -> OpenAIError:
    message = f"Responses API request failed with HTTP {status}"
    code = None
    try:
        parsed = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        parsed = None
    if isinstance(parsed, dict):
        error = parsed.get("error")
        if isinstance(error, dict):
            if isinstance(error.get("message"), str) and error["message"].strip():
                message = _error_message(error["message"])
            code = _optional_code(error.get("code"))
    return OpenAIError(message, status=status, code=code)


def _error_message(message: Any) -> str:
    if isinstance(message, str) and message.strip():
        return message.strip()
    return "Responses API request failed"


def _optional_code(code: Any) -> str | None:
    if isinstance(code, str) and code.strip():
        return code.strip()
    return None
